//! Generated engine offset tables, one module per game build.
//!
//! Generated by `f4x-codegen tables` from CommonLibF4's headers (through clang's MS-ABI
//! layouts); see `provenance/codegen.jsonl`. Use through `f4x-engine`, which picks the
//! table for the running build.
//!
//! ```
//! use f4x_engine_sys::og_1_10_163::RE;
//! assert_eq!(RE::TESForm::SIZE, 0x20);
//! assert_eq!(RE::TESForm::formID, 0x14);
//! assert_eq!(RE::TESObjectREFR::parentCell, 0xB8);
//! ```
#![no_std]

pub mod og_1_10_163;

pub mod og_1_10_163_addresses;

/// A non-virtual engine function: its RVA in one build plus a masked byte signature
/// that is unique in the exe's `.text` (the recipe that re-finds it in any build).
#[derive(Clone, Copy, Debug)]
pub struct Address {
    pub name: &'static str,
    pub rva: u32,
    /// Signature bytes; compare only where `mask` is non-zero.
    pub signature: &'static [u8],
    pub mask: &'static [u8],
}
